xql_query:
// ============================================================
// Rule: CTX_MSBuild Outbound Network Connection to Public Infrastructure
// Vendor: Cortex
// Objective:
// Detect activity associated with CTX_MSBuild Outbound Network Connection to Public Infrastructure.
// Severity: SEV_040_HIGH
// Category: PERSISTENCE
// ============================================================
// MITRE ATT&CK:
// Tactic: TA0011 - Command and Control
// Technique: T1071.001 - Application Layer Protocol: Web Protocols

// Title: CTX - MSBuild Outbound Network Connection to Public Infrastructure
// Description: Detecta msbuild.exe realizando conexão de rede para IP público.
// Pode indicar abuso do MSBuild como proxy execution ou canal de C2 via trusted binary.
// MITRE ATT&CK: T1071.001 (Web Protocols - C2), T1127.001 (MSBuild - Defense Evasion)
//
// NOTA TH: MSBuild com tráfego externo é indicativo de payload .NET inline no projeto.
// A técnica permite execução de shellcode via <UsingTask> em arquivo .csproj/.targets.
// Pivô recomendado: localizar o arquivo .csproj referenciado no command_line e analisar
// o conteúdo inline — procurar por TaskFactory="CodeTaskFactory" com código ofuscado.
//
// ALERT_CATEGORY CORRIGIDO [v2]: "COMMAND_AND_CONTROL" não é categoria válida no XSIAM.
// Categoria corrigida para DEFENSE_EVASION (tática primária do T1127.001).
//
// CORREÇÃO [v2]: Adicionado \Microsoft.NET\Framework64 ao filtro de path.
// Framework64 cobre o msbuild.exe de 64 bits, que é o padrão em sistemas modernos.

config case_sensitive = false
| dataset = xdr_data

// STORY consolida eventos de rede e processo correlacionados no XDR/XSIAM
| filter agent_os_type = ENUM.AGENT_OS_WINDOWS
| filter event_type = ENUM.STORY

| fields
    _time,
    agent_hostname,
    agent_ip_addresses,
    actor_effective_username,
    actor_process_image_name,
    actor_process_image_path,
    actor_process_command_line,
    action_remote_ip,
    action_remote_port,
    agent_external_ip

| alter actor_cmd = lowercase(actor_process_command_line)

// Filtro 1: processo é MSBuild
| filter actor_process_image_name = "msbuild.exe"

// Filtro 2: limita a MSBuild do .NET Framework (32 ou 64 bits)
// Evita falsos positivos de ferramentas de terceiros que renomeiam binários para msbuild.exe
| filter actor_process_image_path contains "\\Microsoft.NET\\Framework"
    or actor_process_image_path contains "\\Microsoft.NET\\Framework64"

// Filtro 3: exclui IPs privados (RFC 1918, loopback e link-local)
| filter not (action_remote_ip ~= "^(10\\.|127\\.|169\\.254\\.|172\\.(1[6-9]|2[0-9]|3[01])\\.|192\\.168\\.)")

// Filtro 4: portas comuns de C2 e web — foco intencional, não exaustivo
// Nota: porta 53 (DNS) não incluída aqui; para C2 via DNS, criar regra dedicada
| filter action_remote_port in (80, 443, 8080, 8443, 8888, 9443)
